class Solution:
    def maxNumberOfGroups(self, usageLimits: List[int]) -> int:
        usageLimits.sort()
        ans = cur = 0
        need = 1
        for v in usageLimits:
            cur += v
            if cur >= need:
                cur -= need
                ans += 1
                need += 1
        return ans

