class Solution:
    def maxNumberOfGroups(self, usageLimits: List[int]) -> int:
        usageLimits.sort()
        def ok(g):
            cur, need = 0, 1
            for v in usageLimits:
                cur += v
                if cur >= need:
                    cur -= need
                    need += 1
                    if need > g:
                        return True
            return need > g
        lo, hi = 1, len(usageLimits)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if ok(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

