int maxNumberOfGroups(vector<int>& usageLimits) {
    sort(usageLimits.begin(), usageLimits.end());
    auto ok = [&](int g) {
        long long cur = 0; int need = 1;
        for (int v : usageLimits) {
            cur += v;
            if (cur >= need) { cur -= need; need++; if (need > g) return true; }
        }
        return need > g;
    };
    int lo = 1, hi = usageLimits.size();
    while (lo < hi) {
        int mid = (lo + hi + 1) / 2;
        if (ok(mid)) lo = mid; else hi = mid - 1;
    }
    return lo;
}

