public int maxNumberOfGroups(int[] usageLimits) {
    Arrays.sort(usageLimits);
    int lo = 1, hi = usageLimits.length;
    while (lo < hi) {
        int mid = (lo + hi + 1) / 2;
        if (ok(usageLimits, mid)) lo = mid; else hi = mid - 1;
    }
    return lo;
}
private boolean ok(int[] a, int g) {
    long cur = 0; int need = 1;
    for (int v : a) {
        cur += v;
        if (cur >= need) { cur -= need; need++; if (need > g) return true; }
    }
    return need > g;
}

